<?php
declare(strict_types=1);
namespace Medbiohim\Services;
final class SupabaseRestProfile {
 public static function bundle(string $uid):array{$base=rtrim((string)\Medbiohim\Support\Env::get('SUPABASE_URL',''),'/');$key=(string)\Medbiohim\Support\Env::get('SUPABASE_SERVICE_KEY','');if($base===''||$key==='')throw new \RuntimeException('Supabase REST fallback is not configured');$get=static function(string $path)use($base,$key):array{$r=\Medbiohim\Support\HttpClient::request('GET',$base.'/rest/v1/'.ltrim($path,'/'),null,['apikey: '.$key,'Authorization: Bearer '.$key],15);if($r['status']<200||$r['status']>=300)throw new \RuntimeException('Supabase REST request failed ('.$r['status'].')');return is_array($r['json'])?$r['json']:[];};$u=$get('users?id=eq.'.rawurlencode($uid).'&select=id,email,full_name,course_number');if(!$u)throw new \RuntimeException('User profile not found');$m=$get('group_memberships?user_id=eq.'.rawurlencode($uid).'&select=group_id,role_in_group');$ids=[];foreach($m as $x)$ids[]=(string)$x['group_id'];$map=[];$groups=[];if($ids)foreach($get('groups?id=in.('.rawurlencode(implode(',',array_map(static fn($x)=>'"'.str_replace('"','\\"',$x).'"',array_unique($ids)))).')&is_active=eq.true&select=id,code,name,course_number,admission_year') as $x)$map[(string)$x['id']]=$x;foreach($m as $x)if(isset($map[(string)$x['group_id']]))$groups[]=array_merge($map[(string)$x['group_id']],['role_in_group'=>$x['role_in_group']??'student']);$u=$u[0];$course=$u['course_number']??null;if($course===null&&$groups)$course=$groups[0]['course_number']??null;$u['course_number']=$course;return ['user'=>$u,'roles'=>[],'groups'=>$groups,'course'=>$course];}
}
